
export interface BossConfigData{
    id:string;
    name:string;
    maxHp:number;
    collisionRadius: number;

    /**
     * 阶段 HP 阈值。stageHpRatios[i] 是"进入阶段 i+1"的 HP 比例。
     * 长度 = 阶段数 - 1。例如 [0.7, 0.35] 表示：
     *   - HP ≤ 70% 进入阶段 1
     *   - HP ≤ 35% 进入阶段 2
     * 初始阶段是 0，不写阈值。
     */
    stageHpRatios: number[];
}


export const BOSS_CONFIG: Record<string, BossConfigData> = {
    whale_boss: {
        id: 'whale_boss',
        name: '吴鲸波',
        maxHp: 3000,
        collisionRadius: 105,
        stageHpRatios: [0.7, 0.35],
    },
};